/* ===== [PERBAIKAN BUG V.0.9.1.0] "Papan Peringkat sama sekali tidak bisa dibuka" =====
   Akar masalah: window.__lbPodiumSlot, window.__lbRowHtml, window.__lbTierStyle, dan
   window.__lbTierProgress DIPANGGIL di mpLoadLeaderboard()/mpLoadMyRank() di bawah,
   tapi keempatnya TIDAK PERNAH didefinisikan di mana pun di seluruh proyek (dicek ulang
   lewat pencarian menyeluruh, termasuk semua file .js.gz) -- jadi setiap kali Papan
   Peringkat dibuka, browser langsung melempar "window.__lbPodiumSlot is not a function"
   / "window.__lbTierStyle is not a function" dan seluruh tab Global maupun Peringkat
   Saya gagal total. Kemungkinan besar keempat fungsi ini hilang saat salah satu sesi
   penggabungan cabang paralel sebelumnya (lihat CHANGELOG_LENGKAP.md) -- kodenya
   memanggil fungsi yang seharusnya sudah ada, tapi definisinya tidak pernah ikut
   tergabung. Keempatnya ditulis ulang dari nol di bawah ini, cocok dengan struktur
   HTML/kelas CSS yang sudah ada (lihat .podium- dan .lb- di
   CSS_1/online_ui.css) dan dengan 7 tingkatan rank dari rankTitleForRating() di
   api/db.php (Bayangan/Jiwa Tersesat/Penyala Api/Pembakar Lilin/Penjelajah Ruang/
   Jiwa Terpilih/Penjaga Gerbang), supaya tampilannya konsisten dgn rank yg dikirim
   backend & dgn PREVIEW_LEADERBOARD.html. ===== */
const LB_TIERS=[{min:2000,name:"Penjaga Gerbang",color:"#ffe27a",bg:"rgba(255,215,0,.2)",border:"rgba(255,215,0,.6)"},{min:1800,name:"Jiwa Terpilih",color:"#c9a0f5",bg:"rgba(150,94,214,.16)",border:"rgba(150,94,214,.45)"},{min:1600,name:"Penjelajah Ruang",color:"#7fd0f0",bg:"rgba(74,160,198,.16)",border:"rgba(74,160,198,.45)"},{min:1400,name:"Pembakar Lilin",color:"#f0a07a",bg:"rgba(206,90,64,.16)",border:"rgba(206,90,64,.45)"},{min:1200,name:"Penyala Api",color:"#f0b87a",bg:"rgba(198,138,74,.16)",border:"rgba(198,138,74,.45)"},{min:1000,name:"Jiwa Tersesat",color:"#c9bd9e",bg:"rgba(168,154,122,.16)",border:"rgba(168,154,122,.45)"},{min:-Infinity,name:"Bayangan",color:"#a8a8a8",bg:"rgba(140,140,140,.16)",border:"rgba(140,140,140,.45)"}];
