function lbMedalIcon(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>'}
window.__lbTierStyle=function(rankTitle){const found=LB_TIERS.find(t=>t.name===rankTitle);return found||LB_DEFAULT_TIER};
