/* ===== [UNIFIKASI LOBI] V.0.8.8.0 -- "Buat Ruangan", "Lobi Publik", dan "Cari Lawan"
   sebelumnya 3 tombol + 3 layar terpisah (overlay-lobby, overlay-public-lobbies,
   overlay-quickmatch) dengan gaya UI yang tidak seragam. Sekarang "Buat Ruangan" dan
   "Lobi Publik" DIGABUNG jadi SATU tombol ("Buat / Gabung Ruangan"), SATU tempat
   (overlay-lobby), SATU UI: host memilih visibilitas Privat/Publik lewat toggle
   .rs-opt-btn yang sama persis gayanya dengan toggle Waktu Giliran/Nyawa Awal di
   Pengaturan Ruangan (lihat CSS_2/matchmaking_ui.css) supaya "serasi", lalu daftar
   lobi publik yang sedang terbuka ditampilkan di layar yang sama utk dijelajahi/gabung.
   overlay-public-lobbies lama sudah dihapus dari index.html -- semua elemen & fungsinya
   sekarang hidup di sini. Layar menunggu (baik nunggu tamu di ruangan privat, nunggu di
   lobi publik, MAUPUN mencari lawan) sekarang SATU overlay yang sama (overlay-quickmatch,
   ditulis ulang isinya secara dinamis lewat mpOpenWaitOverlay) supaya UI-nya seragam
   antara Buat Ruangan/Lobi Publik/Cari Lawan seperti diminta.
   ⚠️ Aturan emas TIDAK berubah: pengaturan kustom (waktu giliran/nyawa/kartu trump)
   TETAP HANYA berlaku utk ruangan visibility=private -- lihat pengecekan
   $visibility==='private' di api/room.php & OnlineEngine::resolveSettingsForRoom di
   api/engine.php. Saat host memilih Publik di sini, tombol Pengaturan Kustom otomatis
   disembunyikan & field settings TIDAK dikirim sama sekali ke server (lihat
   mpCreateRoom) -- lapis pertahanan tambahan dari sisi client, bukan pengganti validasi
   server yang tetap jadi jaminan utamanya. ===== */
let mpCreateVisibility = "private"; // "private" | "public" -- pilihan toggle di form Buat Ruangan, direset ke "private" tiap kali overlay-lobby dibuka
let mpWaitReturnsToLobby = false;   // dipakai tombol Batal di layar tunggu bersama: true = kembali ke overlay-lobby, false = kembali ke Ruang Online saja (dipakai jalur Cari Lawan, sama seperti perilaku lama)
let mpPublicListTimer = null;

function mpStopPublicListPolling() { mpPublicListTimer && (clearInterval(mpPublicListTimer), mpPublicListTimer = null); }

function mpSetCreateVisibility(vis) {
    mpCreateVisibility = vis === "public" ? "public" : "private";
    const isPublic = mpCreateVisibility === "public";
    document.querySelectorAll('#lobby-visibility-group .rs-opt-btn').forEach(btn => {
        btn.classList.toggle("active", btn.getAttribute("data-visibility") === mpCreateVisibility);
    });
    const nameRow = g("lobby-public-name-row");
    nameRow && nameRow.classList.toggle("hidden", !isPublic);
    const settingsBtn = g("room-settings-badge");
    settingsBtn && settingsBtn.classList.toggle("hidden", isPublic);
    const note = g("lobby-public-settings-note");
    note && note.classList.toggle("hidden", !isPublic);
    const createBtn = g("btn-create-room");
    createBtn && !createBtn.disabled && (createBtn.textContent = isPublic ? "Buat Lobi Publik" : "Buat Ruangan");
}

window.mpOpenLobby = function() {
    window.mpOpenOnline();
    if (!window.mpUser) return;
    y("lobby-error", "");
    // Sudah punya ruangan yang masih menunggu (reload halaman, atau baru dibuat lewat
    // Tantangan Teman di Chat) -- langsung ke layar tunggu, jangan tampilkan form lagi.
    if (window.mpRoom && window.mpRoom.status === "waiting") { mpOpenWaitOverlayForRoom(); return; }
    g("lobby-join-code").value = "";
    g("public-lobby-name-input") && (g("public-lobby-name-input").value = "");
    mpSetCreateVisibility("private");
    mpUpdateRoomSettingsBadge();
    v("overlay-lobby", !0);
    mpRefreshPublicLobbyList();
};

window.mpCreateRoom = async function() {
    if (!window.mpUser) return;
    const isPublic = mpCreateVisibility === "public";
    const btn = g("btn-create-room");
    btn && (btn.disabled = !0, btn.textContent = "Membuat...");
    y("lobby-error", "");
    const payload = { action: "create" };
    if (isPublic) {
        payload.visibility = "public";
        const nameInput = g("public-lobby-name-input");
        payload.lobby_name = nameInput ? nameInput.value.trim().slice(0, 40) : "";
    } else if (window.mpRoomSettings) {
        payload.settings = JSON.stringify(window.mpRoomSettings);
    }
    const res = await b("room.php", payload);
    console.log("create room response", res);
    btn && (btn.disabled = !1, btn.textContent = isPublic ? "Buat Lobi Publik" : "Buat Ruangan");
    if (!res.ok) return void y("lobby-error", res.error || "Gagal membuat ruangan.");
    mpStopPublicListPolling();
    window.mpRoom = { id: res.room_id, code: res.room_code, status: "waiting", is_host: !0, visibility: isPublic ? "public" : "private" };
    v("overlay-lobby", !1);
    mpOpenWaitOverlayForRoom();
    q();
};

window.mpJoinRoom = async function() {
    if (!window.mpUser) return;
    const code = g("lobby-join-code").value.trim().toUpperCase();
    if (!code) return void y("lobby-error", "Masukkan kode ruangan.");
    const btn = g("btn-join-room");
    btn && (btn.disabled = !0, btn.textContent = "Bergabung...");
    y("lobby-error", "");
    const res = await b("room.php", { action: "join", room_code: code });
    console.log("join room response", res);
    btn && (btn.disabled = !1, btn.textContent = "Gabung Ruangan");
    if (!res.ok) return void y("lobby-error", res.error || "Gagal bergabung.");
    mpStopPublicListPolling();
    window.mpRoom = { id: res.room_id, code: res.room_code, status: res.status, is_host: !1 };
    v("overlay-lobby", !1);
    H();
};

window.mpJoinByCode = async function(code) {
    window.mpUser && code && (re(), window.mpOpenLobby(), g("lobby-join-code").value = code, await window.mpJoinRoom());
};

/* ===== Lobi Publik: jelajah & gabung -- sekarang bagian dari overlay-lobby yang sama ===== */
function mpRenderPublicLobbyList(list) {
    const box = g("public-lobby-list");
    if (!box) return;
    if (!list || !list.length) { box.innerHTML = '<p class="mp-empty-note">Belum ada lobi publik yang terbuka sekarang. Buat satu di atas, atau coba Cari Lawan.</p>'; return; }
    let html = "";
    for (const room of list) {
        const title = room.lobby_name ? le(room.lobby_name) : "Lobi " + le(room.host_name);
        html += '<div class="public-lobby-row"><div class="public-lobby-avatar">' + le(R(room.host_name)) + '</div><div class="public-lobby-info"><div class="public-lobby-name">' + title + '</div><div class="public-lobby-host">' + le(room.host_name) + " &middot; " + le(room.host_rank) + '</div></div><button class="btn primary public-lobby-join-btn" data-room-id="' + room.room_id + '">Gabung</button></div>';
    }
    box.innerHTML = html;
    box.querySelectorAll(".public-lobby-join-btn").forEach(btn => {
        btn.addEventListener("click", () => window.mpJoinPublicLobby(parseInt(btn.getAttribute("data-room-id"), 10), btn));
    });
}
async function mpRefreshPublicLobbyList() {
    const box = g("public-lobby-list");
    box && (box.innerHTML = '<p class="mp-empty-note">Memuat daftar lobi...</p>');
    const res = await b("matchmaking.php?action=list");
    if (!res.ok) return void y("lobby-error", res.error || "Gagal memuat daftar lobi.");
    mpRenderPublicLobbyList(res.lobbies);
    mpStopPublicListPolling();
    mpPublicListTimer = setInterval(async () => {
        const r2 = await b("matchmaking.php?action=list");
        r2.ok && mpRenderPublicLobbyList(r2.lobbies);
    }, 5000);
}
window.mpJoinPublicLobby = async function(roomId, btnEl) {
    if (!window.mpUser || !roomId) return;
    btnEl && (btnEl.disabled = !0, btnEl.textContent = "...");
    const res = await b("matchmaking.php", { action: "join_public", room_id: roomId });
    if (!res.ok) {
        y("lobby-error", res.error || "Lobi tidak tersedia lagi.");
        const r2 = await b("matchmaking.php?action=list");
        r2.ok && mpRenderPublicLobbyList(r2.lobbies);
        return;
    }
    mpStopPublicListPolling();
    window.mpRoom = { id: res.room_id, code: res.room_code, status: res.status, is_host: !1 };
    v("overlay-lobby", !1);
    H();
};

/* ===== Layar tunggu bersama: dipakai utk 3 skenario (ruangan privat menunggu tamu,
   lobi publik menunggu pemain, & Cari Lawan mencari lawan) supaya UI-nya seragam. ===== */
function mpOpenWaitOverlay(statusText, opts) {
    opts = opts || {};
    mpWaitReturnsToLobby = !!opts.returnToLobby;
    const titleEl = g("mp-wait-title");
    titleEl && (titleEl.textContent = opts.title || "Mencari Lawan");
    const hintEl = g("mp-wait-hint");
    hintEl && (hintEl.textContent = opts.hint || "Lobi ini otomatis publik \u2014 siapa pun yang menekan \u201cCari Lawan\u201d atau menjelajah daftar lobi publik bisa langsung bergabung denganmu.");
    g("quickmatch-status-text").textContent = statusText || "Mencari lawan...";
    g("quickmatch-room-code").textContent = window.mpRoom ? window.mpRoom.code : "------";
    v("overlay-quickmatch", !0);
}
function mpOpenWaitOverlayForRoom() {
    const room = window.mpRoom || {};
    if (room.visibility === "public") {
        mpOpenWaitOverlay("Menunggu pemain lain bergabung ke lobi publikmu...", {
            title: "Menunggu di Lobi Publik",
            hint: "Lobi ini terbuka untuk umum \u2014 siapa pun yang menekan \u201cCari Lawan\u201d atau menjelajah daftar lobi publik bisa langsung bergabung denganmu.",
            returnToLobby: true
        });
    } else {
        mpOpenWaitOverlay("Menunggu jiwa lain bergabung...", {
            title: "Menunggu di Ruangan Privat",
            hint: "Bagikan kode di atas ke temanmu. Begitu ia memasukkan kode ini, permainan langsung dimulai.",
            returnToLobby: true
        });
    }
}
window.mpQuickMatch = async function() {
    if (!window.mpUser) return;
    if (window.mpRoom) { await f("Kamu masih berada di ruangan/lobi lain. Batalkan dulu sebelum mencari lawan baru."); return; }
    const btn = g("btn-online-quickmatch");
    btn && (btn.disabled = !0, btn.textContent = "Mencari...");
    const res = await b("matchmaking.php", { action: "find" });
    btn && (btn.disabled = !1, btn.textContent = "Cari Lawan");
    if (!res.ok) return void await f(res.error || "Gagal mencari lawan. Coba lagi.");
    window.mpRoom = { id: res.room_id, code: res.room_code, status: res.status, is_host: !!res.is_host, visibility: "public" };
    if (res.matched) { H(); return; }
    mpOpenWaitOverlay("Mencari lawan... kamu juga otomatis akan tergabung ke lobi publik siapa pun yang cocok.", { title: "Mencari Lawan", returnToLobby: false });
    q();
};
window.mpCancelWaiting = async function() {
    window.mpRoom && await b("room.php", { action: "leave", room_code: window.mpRoom.code });
    window.mpRoom = null;
    O();
    v("overlay-quickmatch", !1);
    mpWaitReturnsToLobby ? window.mpOpenLobby() : v("overlay-lobby", !1);
};
/* ===== [/UNIFIKASI LOBI] ===== */

/* ===== [PENGATURAN RUANGAN] Kustomisasi ruangan privat: waktu giliran, nyawa awal,
   kartu trump yang diizinkan. window.mpRoomSettings null berarti "klasik" (identik
   perilaku lama) -- mpCreateRoom di atas cuma mengirim field settings kalau ini
   terisi DAN visibilitasnya privat. TIDAK ADA jalur apa pun dari sini yang menyentuh
   Cari Lawan / Lobi Publik. ===== */
let mpCardCatalog = null;
let mpRoomSettingsPending = null;
function mpClassicSettings() {
    const allIds = mpCardCatalog ? mpCardCatalog.cards.map(c => c.id) : [];
    const c = mpCardCatalog ? mpCardCatalog.classic : { turn_seconds: 60, starting_life: 6 };
    return { turn_seconds: c.turn_seconds, starting_life: c.starting_life, enabled_cards: allIds };
}
function mpUpdateRoomSettingsBadge() {
    const el = g("room-settings-badge");
    if (!el) return;
    el.textContent = window.mpRoomSettings ? "\u2699 Pengaturan kustom aktif \u2014 klik utk ubah" : "\u2699 Pengaturan Kustom (opsional)";
    el.classList.toggle("rs-badge-active", !!window.mpRoomSettings);
}
function mpUpdateCardsCountLabel() {
    const el = g("rs-cards-count");
    if (el && mpRoomSettingsPending && mpCardCatalog) el.textContent = mpRoomSettingsPending.enabled_cards.length + " / " + mpCardCatalog.cards.length + " kartu aktif";
}
function mpRenderBtnGroup(containerId, options, currentValue, suffix, classicValue) {
    const box = g(containerId);
    if (!box) return;
    let html = "";
    for (const opt of options) {
        const active = opt === currentValue ? " active" : "";
        html += '<button type="button" class="rs-opt-btn' + active + '" data-value="' + opt + '">' + opt + (suffix || "") + (opt === classicValue ? '<span class="rs-classic-tag">Klasik</span>' : "") + "</button>";
    }
    box.innerHTML = html;
    box.querySelectorAll(".rs-opt-btn").forEach(btn => {
        btn.addEventListener("click", () => {
            box.querySelectorAll(".rs-opt-btn").forEach(b => b.classList.remove("active"));
            btn.classList.add("active");
            const val = parseInt(btn.getAttribute("data-value"), 10);
            if (containerId === "rs-turn-seconds-group") mpRoomSettingsPending.turn_seconds = val;
            else mpRoomSettingsPending.starting_life = val;
        });
    });
}
/* [VISUAL KARTU] Sebelumnya daftar kartu trump di sini cuma checkbox + nama teks polos
   (lihat CHANGELOG). Sekarang tiap kartu dirender sebagai ubin visual berikon (SVG yang
   SAMA dipakai kartu spesial di meja permainan & galeri "Kartu Spesial Online" -- lihat
   iconSvg()/window.ICONS di JSSSYSTEM.js/ASSETS_GAMBAR/sprite_icons.js) supaya host bisa
   langsung KENALI kartunya dari bentuknya, bukan cuma baca namanya -- sesuai permintaan
   "kartu pilihan ... bisa ada visual kartunya apa". Klik ubin = toggle aktif/nonaktif
   (gaya interaksinya sama seperti kartu spesial di meja: klik langsung, bukan checkbox
   kecil), lingkaran centang muncul di pojok saat aktif, warna teal utk kartu eksklusif
   Mode Online (konsisten dgn .gallery-card.online-special/.trump-chip.online-special
   yang sudah ada). */
function mpCardVisualTile(c, selected) {
    const cls = "rs-card-visual" + (selected ? " selected" : "") + (c.online ? " online-special" : "");
    return '<button type="button" class="' + cls + '" data-card-id="' + c.id + '" title="' + le(c.desc) + '">'
        + '<span class="rs-card-visual-check">\u2713</span>'
        + '<span class="rs-card-visual-icon">' + iconSvg(c.icon) + '</span>'
        + '<span class="rs-card-visual-name">' + le(c.name) + '</span>'
        + '</button>';
}
function mpRenderCardList() {
    const box = g("rs-card-list");
    if (!box || !mpCardCatalog) return;
    const groups = [
        { key: "classic", label: "Kartu Klasik", cards: mpCardCatalog.cards.filter(c => !c.online) },
        { key: "online", label: "Kartu Spesial Online", cards: mpCardCatalog.cards.filter(c => c.online) },
    ];
    let html = "";
    for (const grp of groups) {
        html += '<div class="rs-card-group"><div class="rs-card-group-head"><span>' + grp.label + " (" + grp.cards.length + ')</span><span class="rs-group-links"><a href="#" data-group="' + grp.key + '" data-act="all">Pilih Semua</a> &middot; <a href="#" data-group="' + grp.key + '" data-act="none">Kosongkan</a></span></div>';
        html += '<div class="rs-card-visual-grid">';
        for (const c of grp.cards) html += mpCardVisualTile(c, mpRoomSettingsPending.enabled_cards.includes(c.id));
        html += '</div></div>';
    }
    box.innerHTML = html;
    box.querySelectorAll(".rs-card-visual").forEach(tile => {
        tile.addEventListener("click", () => {
            const id = tile.getAttribute("data-card-id");
            const idx = mpRoomSettingsPending.enabled_cards.indexOf(id);
            if (idx === -1) { mpRoomSettingsPending.enabled_cards.push(id); tile.classList.add("selected"); }
            else { mpRoomSettingsPending.enabled_cards.splice(idx, 1); tile.classList.remove("selected"); }
            mpUpdateCardsCountLabel();
        });
    });
    box.querySelectorAll(".rs-group-links a").forEach(a => {
        a.addEventListener("click", ev => {
            ev.preventDefault();
            const grp = groups.find(x => x.key === a.getAttribute("data-group")), act = a.getAttribute("data-act");
            for (const c of grp.cards) {
                const idx = mpRoomSettingsPending.enabled_cards.indexOf(c.id);
                act === "all" && idx === -1 && mpRoomSettingsPending.enabled_cards.push(c.id);
                act === "none" && idx !== -1 && mpRoomSettingsPending.enabled_cards.splice(idx, 1);
            }
            mpRenderCardList();
            mpUpdateCardsCountLabel();
        });
    });
}
function mpRenderRoomSettingsUI() {
    mpRenderBtnGroup("rs-turn-seconds-group", mpCardCatalog.turn_seconds_options, mpRoomSettingsPending.turn_seconds, " dtk", mpCardCatalog.classic.turn_seconds);
    mpRenderBtnGroup("rs-starting-life-group", mpCardCatalog.starting_life_options, mpRoomSettingsPending.starting_life, "", mpCardCatalog.classic.starting_life);
    mpRenderCardList();
    mpUpdateCardsCountLabel();
}
window.mpOpenRoomSettings = async function() {
    y("room-settings-error", "");
    v("overlay-lobby", !1), v("overlay-room-settings", !0);
    if (!mpCardCatalog) {
        g("rs-card-list").innerHTML = '<p class="mp-empty-note">Memuat daftar kartu...</p>';
        const res = await b("room.php?action=card_pool");
        if (!res.ok) { y("room-settings-error", res.error || "Gagal memuat daftar kartu."); return; }
        mpCardCatalog = res;
    }
    mpRoomSettingsPending = window.mpRoomSettings ? JSON.parse(JSON.stringify(window.mpRoomSettings)) : mpClassicSettings();
    mpRenderRoomSettingsUI();
};
window.mpCloseRoomSettings = function() { v("overlay-room-settings", !1), v("overlay-lobby", !0); };
window.mpResetRoomSettingsToClassic = function() { mpRoomSettingsPending = mpClassicSettings(), mpRenderRoomSettingsUI(); };
window.mpSaveRoomSettings = function() {
    if (!mpRoomSettingsPending.enabled_cards.length) { y("room-settings-error", "Pilih setidaknya 1 kartu trump."); return; }
    const classic = mpClassicSettings();
    const isClassic = mpRoomSettingsPending.turn_seconds === classic.turn_seconds && mpRoomSettingsPending.starting_life === classic.starting_life && mpRoomSettingsPending.enabled_cards.length === classic.enabled_cards.length;
    window.mpRoomSettings = isClassic ? null : mpRoomSettingsPending;
    mpUpdateRoomSettingsBadge();
    window.mpCloseRoomSettings();
};
